const items = $input.all();

const normalized = items
  .filter(item => {
    const d = item.json || {};
    const taskName = (d.property_task_name || d.name || '').trim();
    const rawStatus = (d.property_status || '').trim();
    const status = rawStatus.toLowerCase();
    const allowed = status === '' || status === 'not started' || status === 'in progress';
    return taskName !== '' && allowed;
  })
  .map(item => {
    const d = item.json || {};
    const extractDate = (v) => {
      if (!v) return '';
      if (typeof v === 'object' && v.start) return v.start;
      if (typeof v === 'string') return v;
      return '';
    };
    return {
      json: {
        page_id: d.id,
        task_name: (d.property_task_name || d.name || '').trim(),
        status: d.property_status || 'Not started',
        notes: d.property_notes || '',
        due_date: extractDate(d.property_due_date),
        scheduled_start: extractDate(d.property_scheduled_start),
        scheduled_end: extractDate(d.property_scheduled_end),
        priority: d.property_propriety || '',
        project_related_ids: Array.isArray(d.property_project_related) ? d.property_project_related : [],
        created_time: d.property_creation_date || ''
      }
    };
  });

return normalized.length > 0 ? normalized : [{ json: { _empty: true } }];

const item = $input.item;
if (!item || !item.json) return {json: {_skip: true}};
const task = item.json;

const userPrompt = `Evaluate this Notion task and determine if it is easy to complete today.

Task name: ${task.task_name || 'Untitled'}
Status: ${task.status || 'Not started'}
Notes: ${task.notes || 'None'}
Due date: ${task.due_date || 'Not set'}
Priority: ${task.priority || 'Not set'}

Rules:
- Prefer tasks that are specific and actionable.
- Penalize vague, broad, or blocked tasks.
- Penalize tasks requiring deep work longer than 90 minutes.

Respond with ONLY a JSON object:
{"easy_today": boolean, "ease_score": 0-100, "estimated_effort_minutes": number, "confidence": 0-100, "reason": "string", "next_action": "string", "blockers": []}`;

return { json: { ...task, _userPrompt: userPrompt, chatInput: userPrompt } };

const item = $input.item;
if (!item || !item.json) return {json:{easy_today:false,ease_score:0,estimated_effort_minutes:0,confidence:0,reason:'No input',next_action:'',blockers:[],ai_reviewed_at:new Date().toISOString()}};
const merged = item.json;
const task = merged.page_id ? merged : {};
const raw = merged.output || merged.text || merged.message || merged.response || merged.content || '';
let result = {easy_today:false,ease_score:0,estimated_effort_minutes:0,confidence:0,reason:'AI evaluation failed',next_action:'',blockers:[]};
try {
  const str = typeof raw === 'string' ? raw : JSON.stringify(raw);
  const cleaned = str.replace(/```json\s*/gi,'').replace(/```\s*/g,'').trim();
  const m = cleaned.match(/\{[\s\S]*\}/);
  if (m) {
    const p = JSON.parse(m[0]);
    if (p && typeof p === 'object') {
      result = {easy_today:!!p.easy_today,ease_score:Math.min(100,Math.max(0,parseInt(p.ease_score,10)||0)),estimated_effort_minutes:Math.max(0,parseInt(p.estimated_effort_minutes,10)||0),confidence:Math.min(100,Math.max(0,parseInt(p.confidence,10)||0)),reason:String(p.reason||'').slice(0,2000),next_action:String(p.next_action||'').slice(0,2000),blockers:Array.isArray(p.blockers)?p.blockers:[]};
    }
  }
} catch(e) { result.reason = 'Parse error: '+String(e.message||'').slice(0,200); }
return {json:{page_id:task.page_id,task_name:task.task_name,due_date:task.due_date,priority:task.priority,notes:task.notes,project_related_ids:task.project_related_ids,...result,ai_reviewed_at:new Date().toISOString()}};

const item = $input.item;
if (!item || !item.json) return {json:{_skip:true}};
const d = item.json;

const properties = {
  'AI Easy Today': {checkbox: d.easy_today === true},
  'AI Ease Score': {number: typeof d.ease_score === 'number' ? d.ease_score : 0},
  'AI Effort Minutes': {number: typeof d.estimated_effort_minutes === 'number' ? d.estimated_effort_minutes : 0},
  'AI Reason': {rich_text: [{text: {content: String(d.reason||'').slice(0,2000)}}]},
  'AI Next Action': {rich_text: [{text: {content: String(d.next_action||'').slice(0,2000)}}]},
  'AI Confidence': {number: typeof d.confidence === 'number' ? d.confidence : 0},
  'AI Reviewed At': {date: {start: d.ai_reviewed_at || new Date().toISOString()}}
};

if (d.easy_today === true && d.ease_score >= 45 && d.confidence >= 55) {
  properties['AI Recommended'] = {checkbox: true};
}

return {json:{page_id:d.page_id,task_name:d.task_name,easy_today:d.easy_today,ease_score:d.ease_score,confidence:d.confidence,estimated_effort_minutes:d.estimated_effort_minutes,due_date:d.due_date,priority:d.priority,notes:d.notes,notionBody:{properties}}};

const items = $input.all();
const seen = new Set();
const result = [];

for (const item of items) {
  const d = item.json || {};
  const relations = d.property_project_related;
  let list = [];
  if (Array.isArray(relations)) list = relations;
  else if (relations && typeof relations === 'object' && Array.isArray(relations.relation)) list = relations.relation;
  for (const r of list) {
    const id = (r && r.id) ? r.id : (typeof r === 'string' ? r : '');
    if (id && !seen.has(id)) {
      seen.add(id);
      result.push({json: {projectId: id}});
    }
  }
}

return result.length > 0 ? result : [{json: {projectId: null}}];

const items = $input.all();
const projectMap = {};

for (const item of items) {
  const d = item.json || {};
  if (!d.id || d.code) continue;
  const pageId = d.id;
  let title = '';
  const props = d.properties || {};
  for (const key of Object.keys(props)) {
    const prop = props[key];
    if (prop && prop.type === 'title' && Array.isArray(prop.title)) {
      title = prop.title.map(t => t.plain_text || '').join('').trim();
      if (title) break;
    }
  }
  projectMap[pageId] = title || 'Unnamed Project';
}

return [{json: {projectMap}}];

const items = $input.all();

function todayInTimezone(tz) {
  const parts = new Intl.DateTimeFormat('en-CA', {timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit'}).formatToParts(new Date());
  const y = parts.find(p => p.type === 'year')?.value || '1970';
  const m = parts.find(p => p.type === 'month')?.value || '01';
  const d = parts.find(p => p.type === 'day')?.value || '01';
  return `${y}-${m}-${d}`;
}

function extractRichText(val) {
  if (val == null) return '';
  if (typeof val === 'string') return val.trim();
  if (Array.isArray(val)) return val.map(t => (t && t.text && t.text.content) ? t.text.content : '').join('').trim();
  if (val && typeof val === 'object' && Array.isArray(val.rich_text)) return val.rich_text.map(t => (t && t.text && t.text.content) ? t.text.content : '').join('').trim();
  return String(val).trim();
}

function extractProjectLinks(val, projectMap) {
  if (val == null) return [];
  let list = [];
  if (Array.isArray(val)) list = val;
  else if (val && Array.isArray(val.relation)) list = val.relation;
  return list.map(r => {
    const id = (r && r.id) ? r.id : (typeof r === 'string' ? r : '');
    if (!id) return null;
    const name = projectMap[id] || 'Project';
    const clean = id.replace(/-/g, '');
    return clean ? { name, url: `https://www.notion.so/${clean}` } : null;
  }).filter(Boolean);
}

function dueBonus(d) {
  if (!d) return 0;
  try { const diff = (new Date(d) - new Date()) / (1000 * 60 * 60 * 24); return diff <= 1 ? 10 : diff <= 3 ? 6 : 0; } catch (_) { return 0; }
}

function priorityBonus(p) {
  const txt = String(p || '').toLowerCase();
  if (txt.includes('urgent') || txt.includes('high')) return 8;
  if (txt.includes('medium') || txt.includes('meduim')) return 4;
  return 1;
}

function sortByRankDesc(a, b) {
  if (b.rank !== a.rank) return b.rank - a.rank;
  return (b.ease_score || 0) - (a.ease_score || 0);
}

const projectMap = {};
for (const item of items) {
  if (item.json && item.json.projectMap) { Object.assign(projectMap, item.json.projectMap); break; }
}

const rawCandidates = items.map(i => i.json || {}).filter(d => d.id && ((d.property_status || '') !== 'Done')).map(d => {
  const dueDate = d.property_due_date;
  const pageId = d.id || '';
  const notionId = pageId.replace(/-/g, '');
  const task = {
    page_id: pageId,
    task_name: String(d.property_task_name || d.name || '').trim(),
    task_description: extractRichText(d.property_notes ?? d.notes),
    project_links: extractProjectLinks(d.property_project_related, projectMap),
    ease_score: d.property_ai_ease_score || 0,
    confidence: d.property_ai_confidence || 0,
    estimated_effort_minutes: d.property_ai_effort_minutes || 0,
    due_date: typeof dueDate === 'object' && dueDate ? dueDate.start || '' : (dueDate || ''),
    priority: d.property_propriety || '',
    notion_link: notionId ? `https://www.notion.so/${notionId}` : '',
  };
  task.rank = (task.ease_score || 0) + dueBonus(task.due_date) + priorityBonus(task.priority);
  return task;
});

const dedupMap = new Map();
for (const t of rawCandidates) {
  const fallback = (t.task_name || '').toLowerCase().trim();
  const key = t.page_id ? `id:${t.page_id}` : `name:${fallback}`;
  if (!key || key === 'name:') continue;
  const existing = dedupMap.get(key);
  if (!existing || (t.rank || 0) > (existing.rank || 0)) dedupMap.set(key, t);
}

const candidates = Array.from(dedupMap.values()).filter(t => t.page_id);

const staticData = $getWorkflowStaticData('global');
if (!staticData.dailyTaskState || typeof staticData.dailyTaskState !== 'object') staticData.dailyTaskState = {};
if (!staticData.dailyTaskState.sentByPageId || typeof staticData.dailyTaskState.sentByPageId !== 'object') staticData.dailyTaskState.sentByPageId = {};

const sentByPageId = staticData.dailyTaskState.sentByPageId;
const today = todayInTimezone('Europe/Dublin');

const carryOver = [];
const fresh = [];

for (const t of candidates) {
  const prior = sentByPageId[t.page_id];
  const wasSentBeforeToday = !!(prior && prior.lastSentDate && prior.lastSentDate < today);
  if (wasSentBeforeToday) carryOver.push(t);
  else fresh.push(t);
}

carryOver.sort(sortByRankDesc);
fresh.sort(sortByRankDesc);

const carryOverIds = new Set(carryOver.map(t => t.page_id));

const selected = [];
const selectedIds = new Set();

for (const t of carryOver) { if (selected.length >= 5) break; if (selectedIds.has(t.page_id)) continue; selected.push(t); selectedIds.add(t.page_id); }
for (const t of fresh) { if (selected.length >= 5) break; if (selectedIds.has(t.page_id)) continue; selected.push(t); selectedIds.add(t.page_id); }

for (const t of selected) {
  const prev = sentByPageId[t.page_id] || {};
  sentByPageId[t.page_id] = { lastSentDate: today, sentCount: Number(prev.sentCount || 0) + 1, lastTaskName: t.task_name || '', updatedAt: new Date().toISOString() };
}

const activeIds = new Set(candidates.map(t => t.page_id));
for (const pageId of Object.keys(sentByPageId)) { if (!activeIds.has(pageId)) delete sentByPageId[pageId]; }

const carryCount = selected.filter(t => carryOverIds.has(t.page_id)).length;
const lines = selected.map((t, i) => `${i + 1}. ${t.task_name} - score ${t.ease_score} - ${t.estimated_effort_minutes} min`).join('\n');
const summary = selected.length > 0 ? `Today's recommended tasks (${selected.length}/5, carry-over: ${carryCount}):\n${lines}` : 'No recommended tasks today.';

const selectedWithFlags = selected.map(t => ({...t, _carry_over: carryOverIds.has(t.page_id)}));
return [{ json: { summary, easy_tasks: selectedWithFlags, total_easy: selectedWithFlags.length, carry_over_count: carryCount, fresh_count: Math.max(0, selectedWithFlags.length - carryCount), selection_date: today } }];

const items = $input.all();

const projects = items
  .map(item => {
    const d = item.json || {};
    const rawStatus = (d.property_status || d['property_project_status'] || d['property_status_1'] || '').trim();
    const name = (d.property_name || d.property_project_name || d.property_title || d.name || '').trim() || 'Unnamed Project';
    const pageId = (d.id || '').replace(/-/g, '');
    const notionUrl = pageId ? `https://www.notion.so/${pageId}` : '#';
    return { name, status: rawStatus, notionUrl, page_id: d.id || '' };
  })
  .filter(p => {
    const s = p.status.toLowerCase();
    return s.includes('in progress') || s === 'in_progress';
  });

return [{ json: { in_progress_projects: projects } }];

const item = $input.first();
const d = (item && item.json) ? item.json : {};
const tz = 'Europe/Dublin';

const rawItems = Array.isArray(d.items) ? d.items : (d.error ? [] : []);
const events = [];
for (const ev of rawItems) {
  if (!ev || !ev.start) continue;
  const startStr = ev.start.dateTime || ev.start.date;
  const endStr = (ev.end && (ev.end.dateTime || ev.end.date)) || startStr;
  if (!startStr) continue;
  const start = new Date(startStr);
  const end = new Date(endStr);
  if (!isNaN(start) && !isNaN(end) && end > start) {
    events.push({ summary: ev.summary || 'Busy', start, end });
  }
}

events.sort((a, b) => a.start - b.start);

const todayStr = new Date().toLocaleDateString('en-CA', { timeZone: tz });
const dayStart = new Date(todayStr + 'T08:00:00');
const dayEnd = new Date(todayStr + 'T20:00:00');
let cursor = new Date(Math.max(dayStart.getTime(), Date.now()));

const fmt = (dt) => dt.toLocaleTimeString('en-IE', { hour: '2-digit', minute: '2-digit', timeZone: tz });

const freeSlots = [];
for (const ev of events) {
  if (ev.end <= cursor) continue;
  if (ev.start > cursor) {
    const mins = Math.round((ev.start - cursor) / 60000);
    if (mins >= 30) freeSlots.push({ from: fmt(cursor), to: fmt(ev.start), minutes: mins });
  }
  if (ev.end > cursor) cursor = new Date(ev.end);
}
if (cursor < dayEnd) {
  const mins = Math.round((dayEnd - cursor) / 60000);
  if (mins >= 30) freeSlots.push({ from: fmt(cursor), to: fmt(dayEnd), minutes: mins });
}

const calendar_summary = d.error
  ? 'Calendar unavailable (connect Google Calendar credential in n8n)'
  : freeSlots.length > 0
    ? freeSlots.map(s => s.from + '\u2013' + s.to + ' (' + s.minutes + ' min free)').join(', ')
    : events.length > 0 ? 'Fully booked today \u2014 no free slots' : 'No events today \u2014 full day available';

return [{ json: { free_slots: freeSlots, calendar_summary, event_count: events.length } }];

const item = $input.first();
const d = (item && item.json) ? item.json : {};
let weather_summary = 'Weather data unavailable';
try {
  if (d.current_condition && d.current_condition[0]) {
    const c = d.current_condition[0];
    const desc = (c.weatherDesc && c.weatherDesc[0] && c.weatherDesc[0].value) || 'Unknown';
    const temp = c.temp_C || '?';
    const feels = c.FeelsLikeC || '?';
    const humidity = c.humidity || '?';
    const wind = c.windspeedKmph || '?';
    weather_summary = desc + ', ' + temp + '\u00b0C (feels like ' + feels + '\u00b0C), Humidity: ' + humidity + '%, Wind: ' + wind + ' km/h';
    if (d.weather && d.weather[0]) {
      const w = d.weather[0];
      weather_summary += ' | High: ' + (w.maxtempC || temp) + '\u00b0C, Low: ' + (w.mintempC || temp) + '\u00b0C';
    }
  } else if (d.error) {
    weather_summary = 'Weather unavailable';
  }
} catch(e) { weather_summary = 'Could not parse weather'; }
return [{ json: { weather_summary } }];

const item = $input.first();
const d = (item && item.json) ? item.json : {};
const google_task_map = {};
try {
  const rawItems = Array.isArray(d.items) ? d.items : [];
  for (const task of rawItems) {
    if (!task || !task.title) continue;
    const key = task.title.toLowerCase().trim();
    if (key) google_task_map[key] = task.webViewLink || 'https://tasks.google.com/';
  }
} catch(e) {}
return [{ json: { google_task_map } }];

const item = $input.first();
const d = item.json || {};

const easy_tasks = d.easy_tasks || [];
const total_easy = d.total_easy || 0;
const carry_over_count = d.carry_over_count || 0;
const in_progress_projects = d.in_progress_projects || [];
const free_slots = d.free_slots || [];
const calendar_summary = d.calendar_summary || 'Calendar not available';
const weather_summary = d.weather_summary || 'Weather not available';
const google_task_map = d.google_task_map || {};

const escHtml = (s) => {
  if (s == null) return '';
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
};

// Time slot matching with slot advancement — each task gets a sequential unique time
const matchedSlots = {};
if (free_slots.length > 0) {
  const avail = free_slots.map(s => {
    const parts = (s.from || '08:00').split(':').map(Number);
    return { ...s, fromMins: (parts[0]||8)*60 + (parts[1]||0) };
  });
  const byEffort = [...easy_tasks].sort((a,b) => (a.estimated_effort_minutes||30)-(b.estimated_effort_minutes||30));
  for (const task of byEffort) {
    const need = task.estimated_effort_minutes || 30;
    const idx = avail.findIndex(s => s.minutes >= need);
    if (idx >= 0) {
      const sl = avail[idx];
      const pad = n => String(n).padStart(2,'0');
      const sh = Math.floor(sl.fromMins/60), sm = sl.fromMins%60;
      const em = sl.fromMins + need;
      const eh = Math.floor(em/60), emm = em%60;
      matchedSlots[task.page_id] = pad(sh)+':'+pad(sm)+'–'+pad(eh)+':'+pad(emm);
      avail[idx] = {...sl, fromMins: em, minutes: sl.minutes - need};
    }
  }
}

const today = new Date().toLocaleDateString('en-IE', {weekday:'long',year:'numeric',month:'long',day:'numeric',timeZone:'Europe/Dublin'});
const freshCount = Math.max(0, total_easy - carry_over_count);

let highlights = 'You have <strong>' + total_easy + ' recommended task' + (total_easy !== 1 ? 's' : '') + '</strong> today';
if (carry_over_count > 0) highlights += ' &mdash; <strong>' + carry_over_count + '</strong> still pending from yesterday';
if (freshCount > 0) highlights += ', <strong>' + freshCount + ' new</strong>';
highlights += '.';

const calHtml = free_slots.length > 0
  ? free_slots.map(s => '&bull; ' + escHtml(s.from) + '&ndash;' + escHtml(s.to) + ' (' + s.minutes + ' min free)').join('<br>')
  : escHtml(calendar_summary);

const tasksHtml = easy_tasks.length > 0
  ? easy_tasks.map((t, i) => {
      const name = escHtml(t.task_name || 'Task');
      const effort = t.estimated_effort_minutes || 0;
      const score = t.ease_score || 0;
      const notionLink = escHtml(t.notion_link || '#');
      const due = t.due_date ? ' &middot; Due: ' + escHtml(t.due_date) : '';
      const slot = matchedSlots[t.page_id] ? '<br><span style="color:#35d0a6;font-size:13px;">&#128336; Suggested: ' + matchedSlots[t.page_id] + '</span>' : '';
      const badge = t._carry_over ? ' <span style="background:#ff6b6b;color:#fff;font-size:11px;padding:2px 6px;border-radius:3px;">NOT DONE YET</span>' : '';
      const projLinks = (t.project_links || []).map(lk => {
        const href = typeof lk === 'string' ? lk : (lk.url || '#');
        const label = typeof lk === 'string' ? 'Project' : (lk.name || 'Project');
        return '<a href="' + escHtml(href) + '" style="color:#35d0a6;">' + escHtml(label) + '</a>';
      }).join(', ');
      const proj = projLinks ? '<br><span style="color:#aaa;font-size:12px;">&#128193; ' + projLinks + '</span>' : '';
      const taskKey = (t.task_name || '').toLowerCase().trim();
      const gTaskUrl = google_task_map[taskKey];
      const gTaskLink = gTaskUrl
        ? '<a href="' + escHtml(gTaskUrl) + '" style="color:#4285f4;font-size:13px;text-decoration:none;margin-left:12px;">&#9989; Google Tasks &rarr;</a>'
        : '';
      return '<div style="padding:10px 0;border-bottom:1px solid #2a2a2a;"><strong style="font-size:15px;color:#ffffff;">' + (i+1) + '. ' + name + badge + '</strong><br><span style="color:#aaaaaa;font-size:13px;">Ease: ' + score + ' &middot; ~' + effort + ' min' + due + '</span>' + slot + proj + '<br><a href="' + notionLink + '" style="color:#35d0a6;font-size:13px;text-decoration:none;">Open in Notion &rarr;</a>' + gTaskLink + '</div>';
    }).join('')
  : '<p style="color:#aaaaaa;">No recommended tasks today.</p>';

